import { setTimeout as sleep } from "node:timers/promises";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { Submission } from "@earendil-works/pi-durable";

import { ANSWER_KIND } from "./answers.ts";
import type { Thread } from "./thread.ts";
import type { Trigger } from "./triggers.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type SettledRecord = Awaited<ReturnType<Submission["wait"]>>;

export type ThreadResult =
	| { success: true; response: string }
	| { success: false; error: string };

export interface ConversationOptions {
	thread: Thread;
	log: Log;
	timeoutSeconds: number;
	pollIntervalMs: number;
	/** The message to submit for a trigger; `first` is true for the first one of a new thread. */
	message: (trigger: Trigger, first: boolean) => Promise<string>;
	/**
	 * Deliver a result. `alreadyPosted` is set when an earlier run delivered this answer (the trigger was
	 * answered together with another one). Returns where it was posted, recorded so it is never posted twice.
	 */
	deliver: (
		trigger: Trigger,
		result: ThreadResult,
		alreadyPosted: boolean,
	) => Promise<string | undefined>;
	/** Triggers that arrived since the run started; omitted for one-off runs. */
	poll?: () => Promise<Trigger[]>;
	/** The URLs of the questions pi-durable extensions asked in this run so far (see github-ui.ts). */
	asked?: () => readonly string[];
}

const EMPTY_RESPONSE = "Agent returned empty response";
const SUMMARY_SUFFIX = "-summary";
const SUMMARY_PROMPT = `IMPORTANT: You completed your work but did not provide a final text summary. This summary is REQUIRED. Please now write a plain-text summary of what you accomplished, including:
- What changes were made and why
- Which files were modified
- Any errors encountered or remaining issues
- Confirmation that your work is complete

Do NOT call any tools - just provide the text summary.`;

function describeUnanswered(
	record: SettledRecord,
	timedOutAfter: number | undefined,
): string {
	if (record.reason === "aborted" && timedOutAfter !== undefined) {
		return `Timeout after ${timedOutAfter} seconds`;
	}
	if (record.detail === undefined) {
		return record.reason ?? "unanswered";
	}
	const detail =
		typeof record.detail === "string"
			? record.detail
			: JSON.stringify(record.detail);
	return `${record.reason}: ${detail}`;
}

/**
 * Drives a thread through a set of triggers: submits them (new ones join the running conversation), waits for
 * every answer within the timeout, and delivers each answer or failure exactly once.
 */
export class ThreadConversation {
	private readonly handled = new Set<string>();
	private readonly pending = new Set<Promise<void>>();
	private delivering: Promise<void> = Promise.resolve();
	private posted = new Map<string, string>();
	private timedOut = false;
	private readonly options: ConversationOptions;

	constructor(options: ConversationOptions) {
		this.options = options;
	}

	async run(initial: Trigger[]): Promise<void> {
		const { thread, log, timeoutSeconds, pollIntervalMs, poll } = this.options;
		this.posted = await thread.postedResults();
		await this.submitAll(initial);

		const deadline = Date.now() + timeoutSeconds * 1000;
		for (;;) {
			const remaining = deadline - Date.now();
			if (remaining <= 0) {
				this.timedOut = true;
				break;
			}
			if (this.pending.size > 0) {
				const wait = new AbortController();
				const timer = sleep(Math.min(pollIntervalMs, remaining), undefined, {
					signal: wait.signal,
				}).catch(() => undefined);
				// oxlint-disable-next-line eslint/no-await-in-loop -- the poll loop waits between rounds by design
				await Promise.race([Promise.allSettled(this.pending), timer]);
				wait.abort();
			}
			const fresh = poll
				? // oxlint-disable-next-line eslint/no-await-in-loop -- each round polls once, after the wait
					(await poll()).filter((trigger) => !this.handled.has(trigger.key))
				: [];
			if (fresh.length > 0) {
				log.info(
					`${fresh.length} new comment(s) for pi; adding them to the conversation`,
				);
				// oxlint-disable-next-line eslint/no-await-in-loop -- new comments join before the next round
				await this.submitAll(fresh);
			} else if (this.pending.size === 0) {
				break;
			}
		}

		if (this.timedOut) {
			log.warning(`Timeout after ${timeoutSeconds} seconds; aborting the run`);
			await thread.abort();
		}
		await Promise.allSettled(this.pending);
		await this.delivering;
	}

	private async submitAll(triggers: Trigger[]): Promise<void> {
		for (const trigger of triggers) {
			if (!this.handled.has(trigger.key)) {
				const first = this.options.thread.isNew && this.handled.size === 0;
				this.handled.add(trigger.key);
				// oxlint-disable-next-line eslint/no-await-in-loop -- triggers are submitted in order
				const content = await this.options.message(trigger, first);
				this.track(trigger, this.answer(trigger, content));
			}
		}
	}

	private track(trigger: Trigger, result: Promise<SettledResult>): void {
		const settled = (async () => {
			try {
				this.enqueueDelivery(trigger, await result);
			} catch (error) {
				this.options.log.warning(getErrorMessage(error));
			}
		})();
		this.pending.add(settled);
		settled
			.finally(() => {
				this.pending.delete(settled);
			})
			.catch(() => undefined);
	}

	/** Submit and wait; an empty answer is followed by one request for a summary (as pi-action always did). */
	private async answer(
		trigger: Trigger,
		content: string,
	): Promise<SettledResult> {
		const outcome = await this.submitAndWait(trigger, trigger.key, content);
		// An answer an earlier run delivered (or a question it is waiting on) is not asked for again.
		if (!(outcome.empty && !this.timedOut) || this.posted.has(outcome.key)) {
			return outcome;
		}
		this.options.log.warning(
			"Agent returned empty response from first attempt. Re-prompting for a summary.",
		);
		const retry = await this.submitAndWait(
			trigger,
			`${trigger.key}${SUMMARY_SUFFIX}`,
			SUMMARY_PROMPT,
		);
		if (!retry.empty) {
			return retry;
		}
		return {
			key: retry.key,
			empty: true,
			result: {
				success: false,
				error: `Agent failed to provide a response after two attempts. First attempt: ${EMPTY_RESPONSE}. Retry attempt: ${EMPTY_RESPONSE}.`,
			},
		};
	}

	private async submitAndWait(
		trigger: Trigger,
		key: string,
		content: string,
	): Promise<SettledResult> {
		const asked = this.options.asked ?? (() => []);
		const askedBefore = asked().length;
		const { answer } = trigger;
		const submission = await this.options.thread.submit({
			key,
			content,
			data: {
				author: trigger.author.login,
				source: trigger.source,
				...(trigger.url ? { url: trigger.url } : {}),
			},
			...(answer
				? {
						entry: {
							kind: ANSWER_KIND,
							data: {
								key: answer.key,
								kind: answer.kind,
								answer: answer.answer,
								by: answer.by,
								url: answer.url,
							},
						},
					}
				: {}),
		});
		const record = await submission.wait(BACKGROUND_CONTEXT);
		if (record.status === "done" && record.answer !== undefined) {
			const { text, toolCalls } = await this.options.thread.answerText(
				record.answer,
			);
			const questions = asked().slice(askedBefore);
			if (toolCalls && questions.length > 0) {
				// The run ended on a question (its tool round asked to terminate): the answer comes in a later run.
				return {
					key: `answer-${record.answer}`,
					empty: false,
					waiting: questions,
					result: { success: true, response: text },
				};
			}
			return {
				key: `answer-${record.answer}`,
				empty: text === "",
				result: text
					? { success: true, response: text }
					: { success: false, error: EMPTY_RESPONSE },
			};
		}
		const timedOutAfter = this.timedOut
			? this.options.timeoutSeconds
			: undefined;
		return {
			key: `error-${record.id}`,
			empty: false,
			result: {
				success: false,
				error: describeUnanswered(record, timedOutAfter),
			},
		};
	}

	private enqueueDelivery(trigger: Trigger, outcome: SettledResult): void {
		this.delivering = this.delivering
			.then(async () => this.deliver(trigger, outcome))
			.catch((error: unknown) => {
				this.options.log.warning(
					`Failed to deliver result: ${getErrorMessage(error)}`,
				);
			});
	}

	private async deliver(
		trigger: Trigger,
		outcome: SettledResult,
	): Promise<void> {
		const alreadyPosted = this.posted.has(outcome.key);
		if (outcome.waiting) {
			this.options.log.info(
				`pi asked a question and ended its turn; waiting for an answer to ${outcome.waiting.join(", ")}`,
			);
			if (!alreadyPosted) {
				this.posted.set(outcome.key, outcome.waiting[0] ?? "");
				await this.options.thread.markPosted(
					outcome.key,
					outcome.waiting[0] ?? "",
				);
			}
			return;
		}
		if (alreadyPosted && !outcome.result.success) {
			return; // a failure an earlier run already reported
		}
		const url = await this.options.deliver(
			trigger,
			outcome.result,
			alreadyPosted,
		);
		if (url !== undefined && !alreadyPosted) {
			this.posted.set(outcome.key, url);
			await this.options.thread.markPosted(outcome.key, url);
		}
	}
}

interface SettledResult {
	/** `answer-<entryId>` or `error-<submissionId>`: what is delivered once. */
	key: string;
	empty: boolean;
	result: ThreadResult;
	/** The run ended on these questions: nothing is posted, the answers start a later run. */
	waiting?: readonly string[];
}
import { extractTask, hasTrigger } from "./context.ts";
import { isQuestionComment } from "./github-ui.ts";
import { type GitHubClient, toUserType } from "./github.ts";
import {
	type Allowlists,
	sanitizeInput,
	validatePermissions,
} from "./security.ts";
import type {
	GitHubComment,
	GitHubUser,
	TriggerInfo,
	TriggerSource,
	UiAnswer,
} from "./types.ts";

/** One request for pi: an issue/PR body or comment that mentions the trigger phrase. */
export interface Trigger {
	/** Stable per GitHub item; used as the submission's requestId so it is answered once. */
	key: string;
	source: TriggerSource;
	issueNumber: number;
	commentId?: number;
	author: GitHubUser;
	/** The sanitized text, and the task: what follows the trigger phrase. */
	text: string;
	task: string;
	createdAt: string;
	url?: string;
	/** Set when this is the answer to a question from a pi-durable extension; `text` is the message for the model. */
	answer?: UiAnswer;
}

/** Who may run pi, and how they ask: the trigger_phrase and allowed_* inputs. */
export interface TriggerFilter extends Allowlists {
	triggerPhrase: string;
}

export function triggerKey(
	source: TriggerSource,
	issueNumber: number,
	commentId?: number,
): string {
	if (source === "body" || commentId === undefined) {
		return `issue-${issueNumber}`;
	}
	return source === "review_comment"
		? `review-comment-${commentId}`
		: `comment-${commentId}`;
}

function toTrigger(
	item: Omit<Trigger, "key" | "text" | "task">,
	rawText: string,
	triggerPhrase: string,
): Trigger {
	const text = sanitizeInput(rawText);
	return {
		key: triggerKey(item.source, item.issueNumber, item.commentId),
		...item,
		text,
		task: extractTask(text, triggerPhrase),
	};
}

export function triggerFromInfo(
	info: TriggerInfo,
	triggerPhrase: string,
): Trigger {
	return toTrigger(
		{
			source: info.source,
			issueNumber: info.issueNumber,
			...(info.commentId === undefined ? {} : { commentId: info.commentId }),
			author: info.author,
			createdAt: info.createdAt ?? new Date().toISOString(),
			...(info.url ? { url: info.url } : {}),
		},
		info.triggerText,
		triggerPhrase,
	);
}

/**
 * The comments that mention the trigger phrase and whose authors may run pi. Questions from extensions and their
 * `/answer` replies are never triggers, even when they mention the phrase.
 */
export function triggersFromComments(
	comments: GitHubComment[],
	source: Exclude<TriggerSource, "body">,
	issueNumber: number,
	filter: TriggerFilter,
): Trigger[] {
	return comments.flatMap(
		({ id, body, user, author_association, created_at, html_url }) => {
			const text = body ?? "";
			if (
				!(user && hasTrigger(text, filter.triggerPhrase)) ||
				isQuestionComment(text)
			) {
				return [];
			}
			const author: GitHubUser = {
				login: user.login,
				type: toUserType(user.type),
			};
			if (!validatePermissions(author, author_association, filter)) {
				return [];
			}
			const item = {
				source,
				issueNumber,
				commentId: id,
				author,
				createdAt: created_at,
				url: html_url,
			};
			return [toTrigger(item, body ?? "", filter.triggerPhrase)];
		},
	);
}

async function triggersSince(
	client: GitHubClient,
	info: Pick<TriggerInfo, "issueNumber" | "isPullRequest">,
	filter: TriggerFilter,
	since: Date,
): Promise<Trigger[]> {
	const iso = since.toISOString();
	const comments = await client.listIssueComments(info.issueNumber, iso);
	const found = triggersFromComments(
		comments,
		"comment",
		info.issueNumber,
		filter,
	);
	if (info.isPullRequest) {
		const reviews = await client.listReviewComments(info.issueNumber, iso);
		found.push(
			...triggersFromComments(
				reviews,
				"review_comment",
				info.issueNumber,
				filter,
			),
		);
	}
	// `since` filters by update time; keep only comments created since.
	return found.filter(
		(trigger) => Date.parse(trigger.createdAt) >= since.getTime(),
	);
}

/**
 * Every trigger on the thread created after `since` (comments a cancelled or still-pending run never handled,
 * and ones posted while this run works), plus `current`, oldest first and without duplicates.
 */
export async function collectTriggers(
	client: GitHubClient,
	info: Pick<TriggerInfo, "issueNumber" | "isPullRequest">,
	filter: TriggerFilter,
	since: Date | undefined,
	current?: Trigger,
): Promise<Trigger[]> {
	const found = since ? await triggersSince(client, info, filter, since) : [];
	const byKey = new Map<string, Trigger>();
	for (const trigger of current ? [current, ...found] : found) {
		if (!byKey.has(trigger.key)) {
			byKey.set(trigger.key, trigger);
		}
	}
	return [...byKey.values()].toSorted(
		(a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt),
	);
}
import {
	BACKGROUND_CONTEXT,
	type Context,
} from "@earendil-works/chord/context";
import type { Api, Model } from "@earendil-works/pi-ai";
import type { Models } from "@earendil-works/pi-ai/models";
import {
	AssistantEntry,
	type Conversation,
	createRegistry,
	type EntryId,
	type Extension,
	Harness,
	MemoryStorage,
	type Storage,
	type Submission,
} from "@earendil-works/pi-durable";
import { NodeExecutionEnv } from "@earendil-works/pi-durable/env/node";
import { CodingTools } from "@earendil-works/pi-durable/tools";

import { GitStorage } from "./storage/git-storage.ts";
import { git } from "./storage/git.ts";
import { GitSync, isTurnBoundary } from "./storage/sync.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

const context: Context = BACKGROUND_CONTEXT;

const POSTED_KIND = "pi-action.posted";
const COMMENT_KIND = "pi-action.comment";
const KEY_FIELD = "key";
const URL_FIELD = "url";

export const threadRef = (issueNumber: number): string =>
	`refs/pi/threads/${issueNumber}`;

export interface ThreadOptions {
	cwd: string;
	/** The issue or PR; undefined for a one-off prompt, which is kept in memory only. */
	issueNumber?: number | undefined;
	models: Models;
	model: Model<Api>;
	log: Log;
	remote?: string | undefined;
	/** pi-durable extensions from the `extensions` input, installed after the coding tools. */
	extensions?: readonly Extension[];
	/** Variables the tools' shell gets on top of the process environment (see `toolEnv()`). */
	toolEnv?: Readonly<Record<string, string>> | undefined;
}

export interface ThreadInput {
	/** Stable per GitHub item, e.g. `comment-123`: resubmitting it returns the same submission. */
	key: string;
	content: string;
	data: Record<string, string>;
	/** Place the input as this entry instead of a comment (an answer to a question: `ui.answer`). */
	entry?: { kind: string; data: Record<string, string | boolean> } | undefined;
}

interface Persistence {
	ref: string;
	storage: GitStorage;
	sync: GitSync;
	startedAt: Date | undefined;
	isNew: boolean;
}

async function openPersistence(
	options: ThreadOptions,
	issueNumber: number,
): Promise<Persistence> {
	const { cwd, log } = options;
	const ref = threadRef(issueNumber);
	const sync = new GitSync({
		repo: cwd,
		ref,
		log: log.info,
		remote: options.remote,
	});
	const remoteTip = await sync.fetch();
	const storage = await GitStorage.open({
		repo: cwd,
		ref,
		author: {
			name: "pi-action",
			email: "pi-action@users.noreply.github.com",
		},
		onCommit: ({ tip, batches }) => {
			if (isTurnBoundary(batches)) {
				sync.schedule(tip).catch((error: unknown) => {
					log.warning(getErrorMessage(error));
				});
			}
		},
	});
	return {
		ref,
		storage,
		sync,
		isNew: remoteTip === undefined,
		startedAt: remoteTip ? await rootCommitTime(cwd, ref) : undefined,
	};
}

/**
 * One GitHub issue or PR as a durable pi conversation, stored in git on refs/pi/threads/<n> and pushed to the
 * remote at every turn boundary. Without an issue number, the conversation lives in memory for this run only.
 */
export class Thread {
	private closed = false;
	private readonly harness: Harness;
	private readonly root: Conversation;
	private readonly persistence: Persistence | undefined;

	private constructor(
		harness: Harness,
		root: Conversation,
		persistence: Persistence | undefined,
	) {
		this.harness = harness;
		this.root = root;
		this.persistence = persistence;
	}

	static async open(options: ThreadOptions): Promise<Thread> {
		const { cwd } = options;
		const persistence =
			options.issueNumber === undefined
				? undefined
				: await openPersistence(options, options.issueNumber);
		const storage: Storage = persistence?.storage ?? new MemoryStorage();
		const registry = createRegistry();
		registry.install(CodingTools);
		for (const extension of options.extensions ?? []) {
			registry.install(extension);
		}
		const harness = await Harness.open(
			storage,
			{
				models: options.models,
				registry,
				env: ({ cwd: dir }) =>
					new NodeExecutionEnv({
						cwd: dir ?? cwd,
						shellEnv: { ...options.toolEnv },
					}),
				settings: { retry: { maxRetries: 2 } },
			},
			context,
		);
		const agent = {
			model: { provider: options.model.provider, modelId: options.model.id },
			cwd,
		};
		const root = await harness.root(context, { agent });
		await root.configure(agent, context); // the model may differ from the last run's
		harness.resume(); // finish whatever a previous, interrupted run left
		return new Thread(harness, root, persistence);
	}

	/** The thread's ref, when it is stored in git. */
	get ref(): string | undefined {
		return this.persistence?.ref;
	}

	/** A thread nothing was stored for yet (always, in memory). */
	get isNew(): boolean {
		return this.persistence?.isNew ?? true;
	}

	/** When the thread's first commit was made; undefined for a new thread. */
	get startedAt(): Date | undefined {
		return this.persistence?.startedAt;
	}

	/** Comments arriving while a run works join it (steer); otherwise they start one. */
	async submit(input: ThreadInput): Promise<Submission> {
		return this.root.submit(
			{
				type: "input",
				content: input.content,
				requestId: input.key,
				whenBusy: "steer",
				entry: input.entry ?? {
					kind: COMMENT_KIND,
					data: { key: input.key, ...input.data },
				},
			},
			context,
		);
	}

	/** The text of a run's answer, and whether it called tools (a run that ended on a `terminate` round). */
	async answerText(
		answer: EntryId,
	): Promise<{ text: string; toolCalls: boolean }> {
		const entry = await this.root.commit(
			async (tx) => tx.entry(AssistantEntry, answer),
			context,
		);
		const message = entry?.model?.[0];
		if (message?.role !== "assistant") {
			return { text: "", toolCalls: false };
		}
		return {
			text: message.content
				.flatMap((block) => (block.type === "text" ? [block.text] : []))
				.join("")
				.trim(),
			toolCalls: message.content.some((block) => block.type === "toolCall"),
		};
	}

	/** Results already posted (`answer-<entryId>`, `error-<submissionId>`), with their comment URLs. */
	async postedResults(): Promise<Map<string, string>> {
		const posted = new Map<string, string>();
		let cursor: Parameters<Conversation["entries"]>[2];
		do {
			// oxlint-disable-next-line eslint/no-await-in-loop -- pages follow each other
			const page = await this.root.entries(
				{ order: "ascending" },
				500,
				cursor,
				context,
			);
			for (const { kind, data } of page.items) {
				if (kind === POSTED_KIND && typeof data === "object" && data !== null) {
					const key: unknown = Reflect.get(data, KEY_FIELD);
					const url: unknown = Reflect.get(data, URL_FIELD);
					if (typeof key === "string") {
						posted.set(key, typeof url === "string" ? url : "");
					}
				}
			}
			cursor = page.next;
		} while (cursor !== undefined);
		return posted;
	}

	async markPosted(key: string, url: string): Promise<void> {
		await this.root.submit(
			{
				type: "write",
				entry: { kind: POSTED_KIND, data: { key, url } },
				requestId: `posted-${key}`,
			},
			context,
		);
	}

	async abort(): Promise<void> {
		await this.root.abort(context);
	}

	/** Push what is committed so far; throws if the remote moved under us. */
	async push(): Promise<void> {
		await this.persistence?.sync.flush(this.persistence.storage.tip);
	}

	async close(): Promise<void> {
		if (this.closed) {
			return;
		}
		this.closed = true;
		await this.harness.close(context);
		await this.push();
	}
}

/** When the thread's root commit was made. */
async function rootCommitTime(
	cwd: string,
	ref: string,
): Promise<Date | undefined> {
	const out = await git(cwd, [
		"log",
		"--max-parents=0",
		"--format=%cI",
		ref,
	]).catch(() => "");
	const [time] = out.trim().split("\n");
	return time ? new Date(time) : undefined;
}
